{
  "title": "EFF-7b11afa6 Web logs overview",
  "description": "Key traffic metrics for the Kibana sample web logs (kibana_sample_data_logs).",
  "time_range": { "from": "now-7d/d", "to": "now" },
  "panels": [
    {
      "type": "vis",
      "grid": { "x": 0, "y": 0, "w": 12, "h": 8 },
      "config": {
        "type": "metric",
        "title": "Total requests",
        "data_source": { "type": "data_view_reference", "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247" },
        "metrics": [ { "type": "primary", "operation": "count", "label": "Requests" } ]
      }
    },
    {
      "type": "vis",
      "grid": { "x": 12, "y": 0, "w": 12, "h": 8 },
      "config": {
        "type": "metric",
        "title": "5xx responses",
        "data_source": { "type": "data_view_reference", "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247" },
        "query": { "language": "kuery", "expression": "response.keyword >= \"500\" and response.keyword <= \"599\"" },
        "metrics": [ { "type": "primary", "operation": "count", "label": "5xx" } ]
      }
    },
    {
      "type": "vis",
      "grid": { "x": 24, "y": 0, "w": 12, "h": 8 },
      "config": {
        "type": "metric",
        "title": "Unique client IPs",
        "data_source": { "type": "data_view_reference", "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247" },
        "metrics": [ { "type": "primary", "operation": "unique_count", "field": "clientip", "label": "Clients" } ]
      }
    },
    {
      "type": "vis",
      "grid": { "x": 0, "y": 8, "w": 48, "h": 15 },
      "config": {
        "type": "xy",
        "title": "Requests over time",
        "data_source": { "type": "data_view_reference", "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247" },
        "layers": [
          {
            "type": "bar_stacked",
            "data_source": { "type": "data_view_reference", "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247" },
            "x": { "operation": "date_histogram", "field": "timestamp" },
            "breakdown_by": { "operation": "terms", "fields": ["response.keyword"], "columns": 5, "size": 5 },
            "y": [ { "operation": "count", "label": "Requests" } ]
          }
        ]
      }
    }
  ]
}
EOF
H=(-H "Authorization: ApiKey $KIBANA_TEST_API_KEY" -H "kbn-xsrf: true" -H "Content-Type: application/json"); curl -sS "${H[@]}" -X POST "$KIBANA_URL/api/dashboards" -d @dashboard.json | head -c 1500

